package org.diy.liferecorder;
import android.app.*;import android.content.*;import android.os.*;import android.media.*;import android.widget.*;import android.view.Gravity;import java.io.*;
/** Direct enrollment recording is temporary and is never added to the audio library. */
public final class VoiceEnrollmentActivity extends AppScreen {
 private MediaRecorder recorder;private MediaPlayer player;private File sample;private long started;private boolean enrolling;private TextView elapsed;private Button record,save,preview;private final Handler timer=new Handler();
 private final Runnable tick=new Runnable(){public void run(){if(recorder==null)return;long seconds=(SystemClock.elapsedRealtime()-started)/1000;elapsed.setText(seconds+" / 30 秒");if(seconds>=30){stop();return;}timer.postDelayed(this,300);}};
 public void onCreate(Bundle b){super.onCreate(b);frame("录入本人声音");button(body,"‹ 返回",this::finish);body.addView(title("让记录认出你的声音",25));body.addView(text("在安静环境中，用平常语速朗读 5–30 秒。只录你一个人的声音。",14,MUTED));LinearLayout guide=card(body);guide.addView(text("可以这样读",12,SAGE));guide.addView(text("今天我想留住生活里的小事。那些一闪而过的想法，和每一次认真做出的决定，都值得慢慢整理。",18,INK));elapsed=title("00 秒",34);elapsed.setGravity(Gravity.CENTER);guide.addView(elapsed);record=primary(body,"开始录制本人声音",this::begin);preview=button(body,"试听这段声音",this::preview);preview.setEnabled(false);save=button(body,"使用这段声音录入声纹",this::confirm);save.setEnabled(false);body.addView(text("样本只在本机提取声纹，不上传、不进入录音库，完成或退出后删除。",12,MUTED));}
 private void begin(){if(enrolling)return;if(checkSelfPermission("android.permission.RECORD_AUDIO")!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.RECORD_AUDIO"},31);return;}stopPreview();if(sample!=null)sample.delete();try{OfflinePacks packs=new OfflinePacks(this);if(!packs.ready("speaker"))throw new IOException("请先下载并验证声纹识别包");sample=File.createTempFile("enroll-recording-",".m4a",getCacheDir());recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioSamplingRate(16000);recorder.setAudioEncodingBitRate(64000);recorder.setOutputFile(sample.getPath());recorder.prepare();recorder.start();started=SystemClock.elapsedRealtime();record.setText("停止录制");record.setOnClickListener(v->stop());preview.setEnabled(false);save.setEnabled(false);notice.setText("● 正在录制本人声音");timer.post(tick);}catch(Exception e){release();if(sample!=null)sample.delete();notice.setText(e.getMessage()==null?"无法开始录音，请检查麦克风权限":e.getMessage());}}
 private void stop(){if(recorder==null)return;long duration=SystemClock.elapsedRealtime()-started;timer.removeCallbacks(tick);boolean valid=true;try{recorder.stop();}catch(Exception e){valid=false;}release();record.setText("重新录制");record.setOnClickListener(v->begin());preview.setEnabled(valid&&duration>=5000);save.setEnabled(valid&&duration>=5000);notice.setText(valid&&duration>=5000?"录制完成，请试听并确认是你本人的声音":"录音不足 5 秒，请重新录制");}
 private void preview(){stopPreview();try{player=new MediaPlayer();player.setDataSource(sample.getPath());player.setOnPreparedListener(MediaPlayer::start);player.setOnCompletionListener(p->stopPreview());player.prepareAsync();}catch(Exception e){notice.setText("无法试听，请重新录制");}}
 private void confirm(){new LocalDialog(this).setTitle("确认录入本人声音").setMessage("请确认样本中只有你说话。样本会补充到本人的声纹档案，用于本机候选匹配，可在声纹管理中逐个移除。").setPositiveButton("确认录入",(d,w)->enroll()).setNegativeButton("再试听一下",null).show();}
 private void enroll(){if(enrolling||sample==null)return;enrolling=true;stopPreview();record.setEnabled(false);save.setEnabled(false);preview.setEnabled(false);ProgressBar progress=progressBar(body);progress.setIndeterminate(true);background(()->{try{OfflineSpeech.enroll(new OfflinePacks(this),sample);sample.delete();}catch(Exception e){enrolling=false;runOnUiThread(()->{record.setEnabled(true);save.setEnabled(sample!=null&&sample.isFile());preview.setEnabled(sample!=null&&sample.isFile());progress.setVisibility(android.view.View.GONE);});if(isDestroyed()&&sample!=null)sample.delete();throw e;}},()->{setResult(RESULT_OK);finish();});}
 private void stopPreview(){if(player!=null){player.release();player=null;}}
 private void release(){if(recorder!=null){recorder.release();recorder=null;}}
 public void onRequestPermissionsResult(int request,String[] permissions,int[] granted){super.onRequestPermissionsResult(request,permissions,granted);if(request==31&&granted.length>0&&granted[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)begin();}
 protected void onPause(){if(recorder!=null)stop();stopPreview();super.onPause();}
 public void finish(){if(recorder!=null)stop();stopPreview();if(!enrolling&&sample!=null)sample.delete();super.finish();}
 public void onBackPressed(){finish();}
 public void onDestroy(){timer.removeCallbacksAndMessages(null);release();stopPreview();if(!enrolling&&sample!=null)sample.delete();super.onDestroy();}
}
